"""Editable, genre-neutral defaults. Runtime context and schemas remain separate."""
from __future__ import annotations


def _entry(label: str, description: str, text: str, *, version: str = "1") -> dict[str, str]:
    return {"label": label, "description": description, "version": version, "text": text}


